package com.lbos.commercecustomer.client; import com.lbos.commercecustomer.dto.client.platform.*;import java.util.List;import java.util.UUID;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*; @FeignClient(name="lbos-platform", configuration = ServiceBasicAuthFeignConfig.class) public interface PlatformTerritoryClient {@GetMapping("/internal/v1/user-accounts/{id}") UserAccountSummaryResponse user(@PathVariable UUID id); @PostMapping("/internal/v1/territories/validate") TerritoryValidationResponse validate(@RequestBody TerritoryValidationRequest request); @GetMapping("/internal/v1/territories/cities") List<CityLookupResponse> cities(@RequestParam(required=false) String name); @GetMapping("/internal/v1/territories/zones") List<ZoneLookupResponse> zones(@RequestParam("cityId") UUID cityId,@RequestParam(required=false) String name); @GetMapping("/internal/v1/territories/zones/by-cities") List<ZoneLookupResponse> zonesByCities(@RequestParam("cityIds") List<UUID> cityIds);}